%[text] # Efficiency Map of Motor Drive Unit
%[text] This script collects block parameters from the Basic model of Motor Drive Unit component and makes a plot of motor efficiency contour map.
%[text] ## Basic model
mdl = "MotorDriveUnit_Basic_refsub";
MotorDriveUnit_Basic_params
load_system(mdl)
blkpath = mdl + "/Motor & Drive (Driveline)";
info = MotorDriveUnit_getBasicModelBlockInfo(blkpath);
disp(info) %[output:3b7866a9]
%[text] The Basic model has a rotor damper block, whose damping parameter can be passed to the plot function to make a more accurate efficiency plot.
RotorDamping = ModelTool2.getSimscapeValueFromBlockParameter( mdl+"/Rotor damper", "D" );
disp(RotorDamping) %[output:8927d8e6]

fig = MotorDriveUnit_BasicModelEfficiencyPlot( ... %[output:group:02221553] %[output:0945826d]
  ... In road vehicle applications, %[output:0945826d]
  ... maximum motor speed is determined by vehicle top speed, %[output:0945826d]
  ... tire rolling radius, and reduction gear ratio.  %[output:0945826d]
  MaxSpeed = simscape.Value(15000, "rpm"), ... %[output:0945826d]
  ... %[output:0945826d]
  MaxTorque = info.MaxTorque, ... %[output:0945826d]
  MaxPower = info.MaxPower, ... %[output:0945826d]
  EfficiencyPercent = info.EfficiencyPercent, ... %[output:0945826d]
  MeasuredSpeed = info.MeasuredSpeed, ... %[output:0945826d]
  MeasuredTorque = info.MeasuredTorque, ... %[output:0945826d]
  RotorDamping = RotorDamping, ... %[output:0945826d]
  ContourLevelsPercent = simscape.Value([1 60 80 90 92 94 96 97 98 99], "1"), ... %[output:0945826d]
  PlotResolution = 500 ); %[output:group:02221553] %[output:0945826d]
%[text] Save the plot to a PNG file. 
% exportgraphics(fig, "tmp-plot.png")
